-- === STEP 1: Delete SEO content for old IT Services L2/L3 ===
DELETE FROM category_seo_content
WHERE category_id IN (
  SELECT id FROM (
    SELECT id FROM categories
    WHERE parent_id IN (
      SELECT id FROM categories WHERE parent_id = (
        SELECT id FROM categories WHERE slug = 'it-services-agencies' AND level = 1
      )
    )
    UNION
    SELECT id FROM categories
    WHERE parent_id = (
      SELECT id FROM categories WHERE slug = 'it-services-agencies' AND level = 1
    )
  ) AS ids
);

